SELECT browser,
       SUM(cnt) AS count
FROM t_link_browser_stats
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND del_flag = 0
  AND date BETWEEN #{startDate} AND #{endDate}
GROUP BY full_short_url, gid, browser;

SELECT browser,
       SUM(cnt) AS count
FROM t_link_browser_stats
WHERE gid = #{gid}
  AND date BETWEEN #{startDate} and #{endDate}
GROUP BY gid, browser;
